/*
 * A045120  Numbers whose base-4 representation contains exactly two 1's and
 *          one 3.
 * https://oeis.org/A045120
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 24, u16 n <= 48, u32 n <= 48, u64 n <= 48, u128 n <= 48,
 *            big any n
 * Helpers:   cmp_seq_t
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Generated by enumerating all base‑4 integers with exactly two 1’s and one 3. */

#include <stdlib.h>
#include "../utils/cmp_seq_t.h"

#define MAX_CACHE 30000      /* sufficient for n up to a few 10⁴ */
#define MAX_TEMP  25000

static seq_t cache[MAX_CACHE];
static size_t cache_len = 0;
static idx_t next_len = 3;  /* length of numbers to generate next */

static seq_t temp[MAX_TEMP];
static size_t temp_len = 0;

/* Generate all numbers of a given base‑4 length L, append them to cache. */
static void generate_for_length(idx_t L)
{
    temp_len = 0;

    unsigned char dig[32];          /* L ≤ 9 for the required range */
    idx_t rem[32];
    size_t rem_cnt;

    /* choose position of the digit 3 */
    for (idx_t pos3 = 0; pos3 < L; ++pos3) {
        /* choose two positions for the digit 1 */
        for (idx_t pos1a = 0; pos1a < L; ++pos1a) {
            if (pos1a == pos3) continue;
            for (idx_t pos1b = pos1a + 1; pos1b < L; ++pos1b) {
                if (pos1b == pos3) continue;

                /* collect remaining positions */
                rem_cnt = 0;
                for (idx_t p = 0; p < L; ++p) {
                    if (p != pos3 && p != pos1a && p != pos1b)
                        rem[rem_cnt++] = p;
                }

                /* enumerate 0/2 for remaining positions */
                size_t masks = (size_t)1 << rem_cnt;
                for (size_t m = 0; m < masks; ++m) {
                    for (idx_t i = 0; i < L; ++i) dig[i] = 0;
                    dig[pos3] = 3;
                    dig[pos1a] = 1;
                    dig[pos1b] = 1;
                    for (size_t k = 0; k < rem_cnt; ++k)
                        dig[rem[k]] = (m >> k & 1) ? 2 : 0;

                    /* skip leading zero */
                    if (dig[L - 1] == 0) continue;

                    seq_t val = 0;
                    for (idx_t d = L; d-- > 0; )
                        val = val * 4 + dig[d];

                    temp[temp_len++] = val;
                }
            }
        }
    }

    /* sort numbers of this length */
    if (temp_len > 1)
        qsort(temp, temp_len, sizeof(seq_t), cmp_seq_t);

    /* append sorted numbers to global cache */
    for (size_t i = 0; i < temp_len; ++i)
        cache[cache_len++] = temp[i];
}

seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* undefined for n==0, harmless return */

    /* generate terms until we have at least n terms */
    while (cache_len < (size_t)n) {
        generate_for_length(next_len);
        ++next_len;
    }
    return cache[n - 1];
}
